":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s22j06_dato_variable_sin_fuente"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22j06_confunde_sbs_score"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22j06_orientacion_no_autorizada"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22j06_sin_revision_frescura"},"der":{"lit":true}}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s22j06_contenido_recupera":true,"s22j06_promesa_universal":false,"s22j06_dato_variable_sin_fuente":false,"s22j06_confunde_sbs_score":false,"s22j06_orientacion_no_autorizada":false,"s22j06_sin_revision_frescura":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s22j06_contenido_recupera":true,"s22j06_promesa_universal":true,"s22j06_dato_variable_sin_fuente":false,"s22j06_confunde_sbs_score":false,"s22j06_orientacion_no_autorizada":false,"s22j06_sin_revision_frescura":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22j06_contenido_recupera":true,"s22j06_promesa_universal":false,"s22j06_dato_variable_sin_fuente":true,"s22j06_confunde_sbs_score":false,"s22j06_orientacion_no_autorizada":false,"s22j06_sin_revision_frescura":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22j06_contenido_recupera":true,"s22j06_promesa_universal":false,"s22j06_dato_variable_sin_fuente":false,"s22j06_confunde_sbs_score":true,"s22j06_orientacion_no_autorizada":false,"s22j06_sin_revision_frescura":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22j06_contenido_recupera":true,"s22j06_promesa_universal":false,"s22j06_dato_variable_sin_fuente":false,"s22j06_confunde_sbs_score":false,"s22j06_orientacion_no_autorizada":true,"s22j06_sin_revision_frescura":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22j06_contenido_recupera":true,"s22j06_promesa_universal":false,"s22j06_dato_variable_sin_fuente":false,"s22j06_confunde_sbs_score":false,"s22j06_orientacion_no_autorizada":false,"s22j06_sin_revision_frescura":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22j06_contenido_recupera":false,"s22j06_promesa_universal":true,"s22j06_dato_variable_sin_fuente":true,"s22j06_confunde_sbs_score":true,"s22j06_orientacion_no_autorizada":true,"s22j06_sin_revision_frescura":true},"esperado":false}]},"hash":"e9103a18d190fb9f9c638c6ce5b6e3bc826e26a261a73ee34887f1f9f42c6c3b","hash_paquete":"14cd1943bd1e16319eda3983f9f282f335e3900f80c83833b674f49e99d12cde","hash_evaluado":"e9103a18d1","hash_paquete_10":"14cd1943bd"}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; t record; n int:=0; vectors int:=0; b_leg jsonb; b_dep jsonb; b_cfg jsonb; val jsonb; lid int; residual text; diff text; old_desc text; new_desc text; links int:=0; before_replaced int; after_replaced int; direct_hash text; c jsonb;
BEGIN
 SELECT count(DISTINCT legacy_id) INTO before_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true); h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='CANDIDATA' AND hash=p->>'hash') THEN RAISE EXCEPTION 'S22_ATTESTATION_DRIFT %',cd; END IF;
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22_VECTOR_FAIL %',cd; END IF; vectors:=vectors+1; END LOOP;
 n:=n+1;
 END LOOP;
 IF n<>6 OR vectors<>35 THEN RAISE EXCEPTION 'S22_VECTOR_COUNT'; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22_INVARIANT_FAIL'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S22_DPIG03_FAIL'; END IF;
 RAISE NOTICE 'S22J proposal-only: independent judgment pending';
END $s22$;
COMMIT;
